      if (_codigoSala.isNotEmpty) {
        _sincronizarSalaCompartida(silencioso: true);
      }
    });
  }

  Future<void> _cargarDatosLocales() async {
    final prefs = await SharedPreferences.getInstance();
    final savedKey = prefs.getString('gemini_api_key');
    if (savedKey != null && savedKey.isNotEmpty) {
      _apiKey = savedKey;
    }

    final savedModel = prefs.getString('gemini_model');
    if (savedModel != null && savedModel.isNotEmpty) {
      // Si tenia guardado el 2.5-flash que da 404 en su cuenta, migrar a 3-flash-preview
      if (savedModel == 'gemini-2.5-flash' || savedModel == 'gemini-2.5-pro') {
        _modeloSeleccionado = 'gemini-3-flash-preview';
        await prefs.setString('gemini_model', _modeloSeleccionado);
      } else {
        if (!_modelosDisponibles.contains(savedModel)) {
          _modelosDisponibles.insert(0, savedModel);
        }
        _modeloSeleccionado = savedModel;
      }
    }

    _codigoSala = prefs.getString('sala_compartida') ?? '';
    _aliasUsuario = prefs.getString('alias_usuario') ?? 'conrads';
    _nombreArchivoContexto = prefs.getString('ppt_nombre') ?? '';
    _textoExtraidoPpt = prefs.getString('ppt_texto') ?? '';
    _base64PdfContexto = prefs.getString('pdf_base64');

    List<EjercicioResuelto> cargados = [];

    try {
      final rawUnificado = prefs.getString('historial_json_completo_v5') ??
          prefs.getString('historial_json_completo_v4');
      if (rawUnificado != null && rawUnificado.isNotEmpty) {
        final List listaRaw = jsonDecode(rawUnificado);
        cargados = listaRaw
            .map((e) => EjercicioResuelto.fromJson(e as Map<String, dynamic>))
            .toList();
      }
    } catch (_) {}

    if (cargados.isEmpty) {
      try {
        final file = File(_rutaRespaldoFijo);
        if (await file.exists()) {
          final contenido = await file.readAsString();
          if (contenido.isNotEmpty) {
            final List listaRaw = jsonDecode(contenido);
            cargados = listaRaw
                .map((e) =>
                    EjercicioResuelto.fromJson(e as Map<String, dynamic>))
                .toList();
          }
        }
      } catch (_) {}
    }

    if (mounted) {
      setState(() {
        _historial
          ..clear()
          ..addAll(cargados);
      });
    }

    if (_codigoSala.isNotEmpty) {
      _sincronizarSalaCompartida(silencioso: true);
    }
  }

  Future<void> _guardarHistorialLocal() async {
    final listaMap = _historial.map((e) => e.toJson()).toList();
    final jsonCompleto = jsonEncode(listaMap);

    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('historial_json_completo_v5', jsonCompleto);
    } catch (_) {}

    try {
      final file = File(_rutaRespaldoFijo);
      await file.writeAsString(jsonCompleto, flush: true);
    } catch (_) {}
  }

  // Extrae todas las diapositivas de un archivo .pptx (ZIP con XMLs en ppt/slides/slide*.xml)
  Future<void> _cargarArchivoPptOPdf(File archivo) async {
    final nombre = archivo.path.split('/').last;
    final ext = nombre.toLowerCase();

    try {
      if (ext.endsWith('.pptx')) {
        final bytes = await archivo.readAsBytes();
        final archive = ZipDecoder().decodeBytes(bytes);
        final slidesBuffer = StringBuffer();
        int numSlide = 0;

        final slideFiles = archive.files
            .where((f) =>
                f.name.startsWith('ppt/slides/slide') &&
                f.name.endsWith('.xml'))
            .toList();
        slideFiles.sort((a, b) => a.name.compareTo(b.name));

        final regExpTexto = RegExp(r'<a:t[^>]*>(.*?)</a:t>');

        for (final file in slideFiles) {
          numSlide++;
          final content = utf8.decode(file.content as List<int>, allowMalformed: true);
          final matches = regExpTexto.allMatches(content);
          final textoSlide = matches
              .map((m) => m.group(1) ?? '')
              .where((t) => t.trim().isNotEmpty)
              .join(' ');
          if (textoSlide.isNotEmpty) {
            slidesBuffer.writeln('--- Diapositiva $numSlide ---');
            slidesBuffer.writeln(textoSlide);
          }
        }

        final textoFinal = slidesBuffer.toString().trim();
        if (textoFinal.isEmpty) {
          throw Exception('No se encontro texto legible dentro del PPTX.');
        }

        final prefs = await SharedPreferences.getInstance();
        await prefs.setString('ppt_nombre', nombre);
        await prefs.setString('ppt_texto', textoFinal);
        await prefs.remove('pdf_base64');

        if (mounted) {
          setState(() {
            _nombreArchivoContexto = nombre;
            _textoExtraidoPpt = textoFinal;
            _base64PdfContexto = null;
          });
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
                content: Text(
                    'PPT cargado: $nombre ($numSlide diapositivas leidas)')),
          );
        }
      } else if (ext.endsWith('.pdf')) {
        final bytes = await archivo.readAsBytes();
        final b64 = base64Encode(bytes);
        final prefs = await SharedPreferences.getInstance();
        await prefs.setString('ppt_nombre', nombre);
        await prefs.setString('pdf_base64', b64);
        await prefs.remove('ppt_texto');

        if (mounted) {
          setState(() {
            _nombreArchivoContexto = nombre;
            _base64PdfContexto = b64;
            _textoExtraidoPpt = '';
          });
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text('Documento PDF de apoyo cargado: $nombre')),
          );
        }
      } else if (ext.endsWith('.txt') || ext.endsWith('.md')) {
        final texto = await archivo.readAsString();
        final prefs = await SharedPreferences.getInstance();
        await prefs.setString('ppt_nombre', nombre);
        await prefs.setString('ppt_texto', texto);
        await prefs.remove('pdf_base64');

        if (mounted) {
          setState(() {
            _nombreArchivoContexto = nombre;
            _textoExtraidoPpt = texto;
            _base64PdfContexto = null;
          });
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text('Apuntes cargados: $nombre')),
          );
        }
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Error al leer el archivo: $e')),
        );
      }
    }
  }

