  Uri _obtenerUrlSala(String sala) {
    final salaNormalizada = sala.trim().toUpperCase();
    final hashSala = base64Url
        .encode(utf8.encode('saycheese_room_v5_$salaNormalizada'))
        .replaceAll('=', '');
    return Uri.parse('https://kvdb.io/A6Xy9kLmN2pQrStUvWxYz/$hashSala');
  }

  Future<void> _subirASalaCompartida() async {
    if (_codigoSala.trim().isEmpty) return;
    try {
      final resueltos = _historial
          .where((e) => !e.procesando && e.solucion != null)
          .take(20)
          .map((e) => {
                'id': e.id,
                'fecha': e.fecha.toIso8601String(),
                'autor': e.autor,
                'modeloUsado': e.modeloUsado,
                'nombrePptUsado': e.nombrePptUsado,
                'solucion': e.solucion,
                'procesando': false,
              })
          .toList();

      await http.post(
        _obtenerUrlSala(_codigoSala),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode(resueltos),
      );
    } catch (_) {}
  }

  Future<void> _sincronizarSalaCompartida({bool silencioso = false}) async {
    if (_codigoSala.trim().isEmpty) return;
    if (!silencioso && mounted) setState(() => _sincronizando = true);

    try {
      final res = await http.get(_obtenerUrlSala(_codigoSala));
      if (res.statusCode == 200 && res.body.isNotEmpty) {
        final listaRemota = jsonDecode(res.body) as List;
        bool huboCambios = false;

        for (final raw in listaRemota) {
          final itemRemoto =
              EjercicioResuelto.fromJson(raw as Map<String, dynamic>);
          final existeIdx =
              _historial.indexWhere((local) => local.id == itemRemoto.id);
          if (existeIdx == -1) {
            _historial.add(itemRemoto);
            huboCambios = true;
          } else if (_historial[existeIdx].solucion != itemRemoto.solucion &&
              itemRemoto.solucion != null) {
            _historial[existeIdx].solucion = itemRemoto.solucion;
            _historial[existeIdx].modeloUsado = itemRemoto.modeloUsado;
            _historial[existeIdx].nombrePptUsado = itemRemoto.nombrePptUsado;
            _historial[existeIdx].procesando = false;
            huboCambios = true;
          }
        }

        if (huboCambios) {
          _historial.sort((a, b) => b.fecha.compareTo(a.fecha));
          if (mounted) setState(() {});
          await _guardarHistorialLocal();
        }
      }
      await _subirASalaCompartida();
    } catch (_) {
    } finally {
      if (!silencioso && mounted) setState(() => _sincronizando = false);
    }
  }

  Future<void> _abandonarSala() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove('sala_compartida');
    if (mounted) {
      setState(() {
        _codigoSala = '';
        _sincronizando = false;
      });
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Has salido de la sala compartida.')),
      );
    }
  }

  Future<void> _iniciarAgente() async {
    await [
      Permission.photos,
      Permission.storage,
      Permission.manageExternalStorage,
    ].request();

    final dir = Directory(_rutaCarpeta);
    if (!await dir.exists()) {
      try {
        await dir.create(recursive: true);
      } catch (_) {}
    }

    final watcher = DirectoryWatcher(_rutaCarpeta);
    _watcherSub = watcher.events.listen((event) {
      final pathLower = event.path.toLowerCase();
      if (event.type == ChangeType.ADD) {
        if (pathLower.endsWith('.jpg') ||
            pathLower.endsWith('.jpeg') ||
            pathLower.endsWith('.png')) {
          _procesarNuevaFoto(File(event.path));
        } else if (pathLower.endsWith('.pptx') || pathLower.endsWith('.pdf')) {
          // Si mueve un PPTX o PDF a la carpeta SayCheese, se carga solo como base
          _cargarArchivoPptOPdf(File(event.path));
        }
      }
    });

    if (mounted) setState(() => _agenteActivo = true);
  }

  Future<void> _procesarNuevaFoto(File archivoImagen) async {
    await Future.delayed(const Duration(seconds: 2));

    final prefs = await SharedPreferences.getInstance();
    final modeloActual =
        prefs.getString('gemini_model') ?? _modeloSeleccionado;
    final aliasActual = prefs.getString('alias_usuario') ?? _aliasUsuario;

    final nuevoItem = EjercicioResuelto(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      rutaImagen: archivoImagen.path,
      fecha: DateTime.now(),
      autor: aliasActual,
      modeloUsado: modeloActual,
      nombrePptUsado:
          _nombreArchivoContexto.isNotEmpty ? _nombreArchivoContexto : null,
    );

    if (mounted) {
      setState(() {
        _modeloSeleccionado = modeloActual;
        _aliasUsuario = aliasActual;
        _historial.insert(0, nuevoItem);
      });
    }
    await _guardarHistorialLocal();

    await _intentarResolver(nuevoItem);
  }

  Future<void> _intentarResolver(EjercicioResuelto item) async {
    if (item.rutaImagen == null) return;

    final prefs = await SharedPreferences.getInstance();
    final modeloElegido =
        prefs.getString('gemini_model') ?? _modeloSeleccionado;
    final aliasElegido = prefs.getString('alias_usuario') ?? _aliasUsuario;

    if (mounted) {
      setState(() {
        _modeloSeleccionado = modeloElegido;
        _aliasUsuario = aliasElegido;
        item.modeloUsado = modeloElegido;
        item.autor = aliasElegido;
        item.nombrePptUsado =
            _nombreArchivoContexto.isNotEmpty ? _nombreArchivoContexto : null;
        item.procesando = true;
        item.solucion = null;
      });
    }
    await _guardarHistorialLocal();

    try {
      final resultado =
          await _llamarGeminiConAutoRescate(File(item.rutaImagen!), modeloElegido);
      if (mounted) {
        setState(() {
          item.solucion = _limpiarRespuestaMarkdown(resultado['texto']!);
          item.modeloUsado = resultado['modeloReal']!;
          item.procesando = false;
        });
      }
      await _guardarHistorialLocal();
      await _subirASalaCompartida();
    } catch (e) {
      if (mounted) {
        setState(() {
          item.solucion = 'Error al resolver: $e';
          item.procesando = false;
        });
      }
      await _guardarHistorialLocal();
    }
  }

  String _limpiarRespuestaMarkdown(String raw) {
    var limpio = raw.replaceAll('```markdown', '').replaceAll('```', '');
    final lineas = limpio.split('\n');
    final procesadas = lineas.map((linea) {
      if (linea.startsWith('    ') &&
          !linea.trimLeft().startsWith('*') &&
          !linea.trimLeft().startsWith('-') &&
          !RegExp(r'^\d+\.').hasMatch(linea.trimLeft())) {
        return linea.trimLeft();
      }
      return linea;
    }).toList();
    return procesadas.join('\n').trim();
  }

  // Consulta en vivo a la API de Google que modelos Flash/Pro tienen permiso en esta cuenta
  Future<List<String>> _descubrirModelosActivosEnCuenta(String apiKey) async {
    try {
      final url = Uri.parse(
          'https://generativelanguage.googleapis.com/v1beta/models?key=$apiKey');
      final res = await http.get(url);
      if (res.statusCode == 200) {
        final data = jsonDecode(res.body);
        final models = data['models'] as List? ?? [];
        final disponibles = <String>[];
        for (final m in models) {
          final name = (m['name'] as String? ?? '').replaceFirst('models/', '');
          final methods = (m['supportedGenerationMethods'] as List? ?? [])
              .map((e) => e.toString())
              .toList();
          if (methods.contains('generateContent') &&
              name.startsWith('gemini') &&
              !name.contains('embedding') &&
              !name.contains('imagen') &&
              !name.contains('tts')) {
            disponibles.add(name);
          }
        }
        // Priorizar modelos flash (que tienen cuota gratuita alta y no dan 429)
        disponibles.sort((a, b) {
          final aFlash = a.contains('flash') ? 0 : 1;
          final bFlash = b.contains('flash') ? 0 : 1;
          if (aFlash != bFlash) return aFlash.compareTo(bFlash);
          return b.compareTo(a);
        });
        return disponibles;
      }
    } catch (_) {}
    return [];
  }

  // Intenta primero con el modelo elegido; si Google devuelve 404 (modelo retirado) o 429 (cuota 0),
  // busca automaticamente el modelo Flash activo en tu cuenta y resuelve la hoja sin fallar.
  Future<Map<String, String>> _llamarGeminiConAutoRescate(
      File imagen, String modeloPreferido) async {
    final keyLimpia = _apiKey.trim();
    if (keyLimpia.isEmpty) {
      throw Exception(
          'Configura tu Gemini API Key (AIzaSy...) en el icono de engranaje superior.');
    }

    final bytes = await imagen.readAsBytes();
    final base64Image = base64Encode(bytes);

    final colaModelos = <String>[
      modeloPreferido.trim(),
      'gemini-3-flash-preview',
      'gemini-3.8-flash',
      'gemini-2.0-flash',
      'gemini-2.5-flash-lite',
    ];

    // Agregar tambien cualquier modelo activo que reporte directamente la cuenta del usuario
    final detectados = await _descubrirModelosActivosEnCuenta(keyLimpia);
    for (final d in detectados) {
      if (!colaModelos.contains(d)) {
        colaModelos.add(d);
      }
    }

    String promptTexto =
        "Resuelve todos los ejercicios de esta hoja paso a paso. Usa formato Markdown claro, enumera cada ejercicio y destaca el resultado final en negrita (NUNCA uses bloques de codigo ni sangrias de 4 espacios para el resultado final).";

    if (_nombreArchivoContexto.isNotEmpty && _textoExtraidoPpt.isNotEmpty) {
      promptTexto +=
          "\n\nIMPORTANTE: Responde y resuelve los ejercicios basandote ESTRICTAMENTE en el siguiente contenido de la presentacion PowerPoint / documento ($_nombreArchivoContexto):\n\n$_textoExtraidoPpt";
    } else if (_nombreArchivoContexto.isNotEmpty &&
        _base64PdfContexto != null) {
      promptTexto +=
          "\n\nIMPORTANTE: Responde y resuelve los ejercicios de la imagen basandote ESTRICTAMENTE en el documento PDF adjunto ($_nombreArchivoContexto).";
    }

    final List<Map<String, dynamic>> parts = [
      {"text": promptTexto},
      {
        "inline_data": {
          "mime_type": "image/jpeg",
          "data": base64Image,
        }
      }
    ];

    if (_base64PdfContexto != null && _base64PdfContexto!.isNotEmpty) {
      parts.add({
        "inline_data": {
          "mime_type": "application/pdf",
          "data": _base64PdfContexto,
        }
      });
    }

    String ultimoError = '';
    final visitados = <String>{};

    for (final modActual in colaModelos) {
      if (modActual.isEmpty || visitados.contains(modActual)) continue;
      visitados.add(modActual);

      final url = Uri.parse(
        'https://generativelanguage.googleapis.com/v1beta/models/$modActual:generateContent?key=$keyLimpia',
      );

      final Map<String, dynamic> payload = {
        "contents": [
          {"parts": parts}
        ],
      };

      http.Response? response;
      for (int i = 0; i < 2; i++) {
        try {
          response = await http.post(
            url,
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode(payload),
          );
          break;
        } catch (e) {
          if (i == 1) ultimoError = e.toString();
          await Future.delayed(const Duration(seconds: 2));
        }
      }

      if (response == null) continue;

      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        final respParts = data['candidates'][0]['content']['parts'] as List;
        final textPart = respParts.lastWhere(
          (p) => p.containsKey('text') && p['thought'] != true,
          orElse: () => respParts.last,
        );
        // Si tuvo que cambiar de modelo porque el anterior daba 404 o 429, guardamos el que si funciona
        if (modActual != modeloPreferido) {
          final prefs = await SharedPreferences.getInstance();
          await prefs.setString('gemini_model', modActual);
          if (mounted) {
            setState(() {
              if (!_modelosDisponibles.contains(modActual)) {
                _modelosDisponibles.insert(0, modActual);
              }
              _modeloSeleccionado = modActual;
            });
          }
        }
        return {
          'texto': textPart['text'].toString(),
          'modeloReal': modActual,
        };
      } else if (response.statusCode == 404 || response.statusCode == 429) {
        // Si el mensaje de error 404 sugiere un modelo especifico (ej. models/gemini-3.8-flash), extraerlo y probarlo
        final matchSugerido =
            RegExp(r'models/(gemini-[a-zA-Z0-9._-]+)').firstMatch(response.body);
        if (matchSugerido != null) {
          final sugerido = matchSugerido.group(1)!;
          if (!visitados.contains(sugerido)) {
            colaModelos.insert(colaModelos.indexOf(modActual) + 1, sugerido);
          }
        }
        ultimoError =
            'Codigo ${response.statusCode} en $modActual: ${response.body}';
        continue;
      } else {
        throw Exception(
            'Codigo ${response.statusCode} en $modActual: ${response.body}');
      }
    }

    throw Exception(ultimoError);
  }

