  String _generarCodigoSalaAleatorio() {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    final rnd = Random();
    final sufijo =
        List.generate(4, (_) => chars[rnd.nextInt(chars.length)]).join();
    return 'SALA-$sufijo';
  }

