          const Divider(height: 1),
          Expanded(
            child: Markdown(
              data: ejercicio.solucion ?? 'Sin respuesta.',
              selectable: true,
              styleSheet: markdownDarkSheet,
            ),
          ),
        ],
      ),
    );
  }
}
